:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --border: #2a2a4a;
  --focus: #ff6b81;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border: 2px solid var(--border);
  border-radius: 12px;
  padding: 28px 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 0.95rem;
}

.label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
  font-size: 0.95rem;
}

textarea {
  width: 100%;
  padding: 12px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  font-family: inherit;
  font-size: 1rem;
  resize: vertical;
  min-height: 140px;
  transition: border-color 0.15s;
}

textarea:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.25);
}

textarea::placeholder {
  color: var(--muted);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin: 20px 0;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 4px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: 8px;
}

.stat-value {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--accent);
  line-height: 1.2;
}

.stat-label {
  font-size: 0.75rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-top: 2px;
  text-align: center;
}

button {
  width: 100%;
  padding: 12px 20px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

button:hover {
  background: var(--focus);
}

button:focus-visible {
  outline: none;
  border-color: var(--text);
  box-shadow: 0 0 0 3px rgba(255, 107, 129, 0.4);
}

button:active {
  transform: scale(0.98);
  background: #c73550;
}

@media (max-width: 400px) {
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .card {
    padding: 20px 16px;
  }
  h1 {
    font-size: 1.35rem;
  }
}

(function () {
  'use strict';

  var textInput = document.getElementById('text-input');
  var wordCount = document.getElementById('word-count');
  var charCount = document.getElementById('char-count');
  var sentenceCount = document.getElementById('sentence-count');
  var readingTime = document.getElementById('reading-time');
  var clearBtn = document.getElementById('clear-btn');

  var WORDS_PER_MINUTE = 200;

  function countWords(text) {
    var trimmed = text.trim();
    if (trimmed === '') return 0;
    return trimmed.split(/\s+/).length;
  }

  function countSentences(text) {
    var trimmed = text.trim();
    if (trimmed === '') return 0;
    var parts = trimmed.split(/[.!?]+/).filter(function (part) {
      return part.trim().length > 0;
    });
    return parts.length;
  }

  function estimateReadingTime(words) {
    if (words === 0) return 0;
    return Math.max(1, Math.ceil(words / WORDS_PER_MINUTE));
  }

  function update() {
    var text = textInput.value;
    var words = countWords(text);
    var chars = text.length;
    var sentences = countSentences(text);
    var minutes = estimateReadingTime(words);

    wordCount.textContent = words;
    charCount.textContent = chars;
    sentenceCount.textContent = sentences;
    readingTime.textContent = minutes;
  }

  function clearAll() {
    textInput.value = '';
    update();
    textInput.focus();
  }

  textInput.addEventListener('input', update);
  clearBtn.addEventListener('click', clearAll);

  update();
})();
